input.command:
mkdir bootstrap && cat > .gitignore <<'E'
.terraform/
*.tfstate
*.tfstate.*
*.tfplan
crash.log
crash.*.log
.terraformrc
terraform.rc
*.tfvars
*.auto.tfvars
E
cat > bootstrap/versions.tf <<'E'
terraform {
  required_version = ">= 1.11.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}
E
cat > bootstrap/providers.tf <<'E'
provider "aws" {
  region = var.region
}
E
cat > bootstrap/variables.tf <<'E'
variable "region" {
  type        = string
  description = "AWS region the state bucket and its KMS key are created in."
  default     = "eu-north-1"
}

variable "state_bucket_name" {
  type        = string
  description = "Name of the S3 bucket that holds Terraform state. S3 bucket names are global, so choose one unique to your organisation."

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$", var.state_bucket_name))
    error_message = "The bucket name must be 3-63 characters of lowercase letters, digits, dots and hyphens."
  }
}

variable "state_access_principal_arns" {
  type        = list(string)
  description = "IAM role or user ARNs allowed to read and write state. Every other principal is denied by the bucket policy. Include the identity that runs this bootstrap configuration, or it locks itself out."

  validation {
    condition     = length(var.state_access_principal_arns) > 0
    error_message = "Provide at least one principal ARN, otherwise nobody can use the bucket."
  }
}
E
cat > bootstrap/main.tf <<'E'
data "aws_iam_policy_document" "state_key" {
  # Key administration stays with the account; use of the key for state is
  # limited to the listed principals through the bucket policy and grants below.
  statement {
    sid       = "AccountAdministration"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid       = "StatePrincipalsUseKey"
    actions   = ["kms:Encrypt", "kms:Decrypt", "kms:GenerateDataKey"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = var.state_access_principal_arns
    }
  }
}

data "aws_caller_identity" "current" {}

resource "aws_kms_key" "state" {
  description         = "Encrypts Terraform state in ${var.state_bucket_name}"
  enable_key_rotation = true
  policy              = data.aws_iam_policy_document.state_key.json
}

resource "aws_kms_alias" "state" {
  name          = "alias/${var.state_bucket_name}"
  target_key_id = aws_kms_key.state.key_id
}

# Access logging is left to the organisation's central log bucket.
#tfsec:ignore:aws-s3-enable-bucket-logging
resource "aws_s3_bucket" "state" {
  bucket = var.state_bucket_name

  # State is the only copy of the team's resource mapping.
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.state.arn
    }
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  # Versioning is the rollback path for corrupt state; keep it bounded.
  rule {
    id     = "expire-old-state-versions"
    status = "Enabled"

    filter {}

    noncurrent_version_expiration {
      noncurrent_days = 90
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }

  depends_on = [aws_s3_bucket_versioning.state]
}

data "aws_iam_policy_document" "state_bucket" {
  statement {
    sid       = "DenyInsecureTransport"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.state.arn, "${aws_s3_bucket.state.arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid       = "DenyAllButStatePrincipals"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.state.arn, "${aws_s3_bucket.state.arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "ArnNotLike"
      variable = "aws:PrincipalArn"
      values   = var.state_access_principal_arns
    }
  }
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id
  policy = data.aws_iam_policy_document.state_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.state]
}
E
cat > bootstrap/outputs.tf <<'E'
output "state_bucket_name" {
  description = "Name of the state bucket, for the bucket value in the root configuration's backend.hcl."
  value       = aws_s3_bucket.state.id
}

output "state_kms_key_arn" {
  description = "ARN of the KMS key that encrypts state, for the kms_key_id value in the root configuration's backend.hcl."
  value       = aws_kms_key.state.arn
}
E
cat > backend.hcl <<'E'
# Non-secret backend metadata. Replace both values with the bootstrap outputs.
bucket     = "example-org-terraform-state"
kms_key_id = "arn:aws:kms:eu-north-1:111122223333:key/00000000-0000-0000-0000-000000000000"
E
cat >> versions.tf <<'E'
E
python3 - <<'E'
p='versions.tf'
s=open(p).read().replace('>= 1.10.0','>= 1.11.0')
s=s.replace('terraform {\n','terraform {\n  # bucket and kms_key_id are supplied with -backend-config=backend.hcl\n  backend "s3" {\n    key          = "reports/terraform.tfstate"\n    region       = "eu-north-1"\n    encrypt      = true\n    use_lockfile = true\n  }\n\n',1)
open(p,'w').write(s)
E
terraform fmt -recursive -check -diff; cat versions.tf

